fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let l = s.len();
    let p = l - (l % 3); // largest multiple of 3 <= l

    let mut res = Vec::with_capacity(l);

    for i in 0..l {
        if i < p {
            match i % 3 {
                0 => res.push(s[i + 2]),
                1 => res.push(s[i - 1]),
                _ => res.push(s[i - 1]), // i % 3 == 2
            }
        } else {
            res.push(s[i]);
        }
    }

    res
}